<script setup lang="ts">
const value=ref<any>(),message=ref(''),loading=ref(false)
async function refresh(){loading.value=true;try{const response:any=await $fetch('/api/v1/nodes/runtime');value.value=response.data;message.value=''}catch(error:any){message.value=error.statusCode===403?'Platform administrator permission required':'Runtime diagnostics unavailable'}finally{loading.value=false}}
onMounted(refresh)
</script>
<template><section class="section-card space-y-4 mb-6"><div class="flex justify-between gap-3"><h3 class="font-semibold">PostgreSQL workers</h3><button class="btn btn-secondary" :disabled="loading" @click="refresh">Refresh runtime</button></div><p v-if="message">{{message}}</p><template v-if="value"><p>Role: {{value.role}} · {{value.ready?'Ready':'Not ready'}} · Outbox pending {{value.outbox.pending}} / dead {{value.outbox.dead}}</p><p class="text-sm">Scheduled checkers: HTTP, keyword and JSON query. Other legacy checkers remain stored and require a bounded worker adapter before scheduling.</p><div class="overflow-auto"><table class="table"><thead><tr><th>Instance</th><th>Role</th><th>Inflight / limit</th><th>Last seen</th><th>State</th></tr></thead><tbody><tr v-for="instance in value.instances" :key="instance.instanceId"><td class="font-mono text-xs">{{instance.instanceId}}</td><td>{{instance.role}}</td><td>{{instance.inflight}} / {{instance.effectiveConcurrency}}</td><td>{{new Date(instance.lastSeen).toLocaleTimeString()}}</td><td>{{instance.state==='draining'?'Draining':instance.state==='offline'?'Offline':'Running'}}</td></tr></tbody></table></div><p v-if="value.unsupported.length">Unsupported active monitors: {{value.unsupported.map((row:any)=>`${row.type}: ${row.count}`).join(', ')}}</p></template></section></template>
